-- Contrairement à setup_complet.sql (qui DROP puis recrée toutes les
-- tables), ce script est additif : à exécuter UNE SEULE FOIS sur la
-- base de production existante, sans rien supprimer.
--
-- Avant de lancer :
--   1. Faire une sauvegarde (./BDD/backup.sh ou mysqldump manuel).
--   2. Vérifier qu'aucun exercice d'id 76 à 95 n'existe déjà en base
--      (SELECT id FROM Exercices WHERE id BETWEEN 76 AND 95;) —
--      sinon les INSERT plus bas échoueront sur la clé primaire.
--   3. Ne PAS relancer ce fichier une seconde fois tel quel (les
--      INSERT ne sont pas idempotents).
--
-- Contenu :
--   A. Colonnes FSRS sur Revisions (remplace l'algo SM-2 par FSRS,
--      cf. backend/src/controllers/queteController.ts)
--   B. 17 nouveaux exercices (détection/discrimination non-verbales,
--      classification, intrus, consignes progressives, dialogues)
--   C. 3 exercices pour activer le composant "décision orthographique"
--      (codé mais jusqu'ici sans aucun contenu en base)
--   D. Élargissement de 12 banques de mots/items trop courtes
-- ================================================================

-- ── A. Colonnes FSRS sur Revisions ─────────────────────────────
ALTER TABLE Revisions
  ADD COLUMN stabilite         DOUBLE DEFAULT NULL AFTER nb_revisions,
  ADD COLUMN difficulte        DOUBLE DEFAULT NULL AFTER stabilite,
  ADD COLUMN etat              TINYINT NOT NULL DEFAULT 0 AFTER difficulte,
  ADD COLUMN nb_echecs         INT NOT NULL DEFAULT 0 AFTER etat,
  ADD COLUMN derniere_revision DATETIME DEFAULT NULL AFTER nb_echecs;

-- ── B. + C. + D. Nouveaux exercices et banques élargies ────────

-- ── Nouveaux exercices : détection/discrimination non-verbales, classification,
--    intrus, consignes progressives, dialogues (cf. référentiel détection/discrimination/
--    identification/compréhension) ───────────────────────────────

INSERT INTO `Exercices` (`id`, `titre`, `niveau`, `description`, `audio_url`, `categorie_id`, `type_exercice`, `contenu`) VALUES
(76,'Jouets sonores','facile','Cliquez chaque fois que vous entendez un son de jouet ou d\'objet familier (hochet, clochette, grelot...).','',3,'detecter',NULL),
(77,'Cris d\'animaux et bruits du quotidien','moyen','Cliquez à chaque son : cri d\'animal, klaxon, sonnette, aboiement... Le rythme est plus dense qu\'en niveau facile.','',3,'detecter',NULL),
(78,'Détection en environnement bruyant','difficile','Repérez chaque son alors qu\'un bruit de fond est présent — comme dans une pièce animée ou une rue passante.','',3,'detecter',NULL),
(79,'Sons purs : pareil ou différent ?','facile','Deux sons sont joués l\'un après l\'autre. Sont-ils identiques ou différents ? Les hauteurs sont très éloignées.','',5,'distinguer',NULL),
(80,'Comparaison fine de hauteur sonore','moyen','Comparez deux sons dont la hauteur se rapproche — un écart d\'un ton environ.','',5,'distinguer',NULL),
(81,'Discrimination fine en bruit de fond','difficile','Comparez deux sons très proches (un demi-ton d\'écart) avec un bruit de fond présent en continu.','',5,'distinguer',NULL),
(82,'Nature ou machine ?','facile','Écoutez la description du bruit et classez-le : vient-il de la nature ou d\'une machine ?','',4,'reconnaitre','{"categories": ["Nature", "Machine"], "consigne_categorisation": "Ce bruit vient-il de la nature ou d\'une machine ?", "classification": [{"description": "Le vent qui souffle fort dans les arbres.", "categorie": "Nature"}, {"description": "Un moteur de voiture qui démarre.", "categorie": "Machine"}, {"description": "Des vagues qui s\'écrasent sur la plage.", "categorie": "Nature"}, {"description": "Une perceuse électrique.", "categorie": "Machine"}, {"description": "La pluie qui tombe sur un toit.", "categorie": "Nature"}, {"description": "Un aspirateur en marche.", "categorie": "Machine"}, {"description": "Le tonnerre qui gronde au loin.", "categorie": "Nature"}, {"description": "Une imprimante qui fonctionne.", "categorie": "Machine"}], "instructions": "Votre partenaire lit la description d\'un bruit. Dites s\'il provient de la nature ou d\'une machine.", "consigne_partenaire": "Lisez chaque description à voix haute, dans un ordre aléatoire."}'),
(83,'Familles d\'instruments de musique','moyen','Classez chaque instrument décrit dans sa famille : percussions, vent ou cordes.','',4,'reconnaitre','{"categories": ["Percussions", "Vent", "Cordes"], "consigne_categorisation": "À quelle famille appartient cet instrument ?", "classification": [{"description": "Le tambour, que l\'on frappe avec des baguettes.", "categorie": "Percussions"}, {"description": "La flûte traversière, dans laquelle on souffle.", "categorie": "Vent"}, {"description": "Le violon, dont on frotte les cordes avec un archet.", "categorie": "Cordes"}, {"description": "Les cymbales, que l\'on entrechoque.", "categorie": "Percussions"}, {"description": "La trompette, dans laquelle on souffle avec les lèvres.", "categorie": "Vent"}, {"description": "La guitare, dont on pince les cordes.", "categorie": "Cordes"}, {"description": "Le xylophone, que l\'on frappe avec des maillets.", "categorie": "Percussions"}, {"description": "Le saxophone, dans lequel on souffle.", "categorie": "Vent"}, {"description": "La harpe, dont on pince les cordes.", "categorie": "Cordes"}], "instructions": "Votre partenaire décrit un instrument. Dites à quelle famille il appartient.", "consigne_partenaire": "Lisez chaque description à voix haute, dans un ordre aléatoire."}'),
(84,'Bruits domestiques par pièce','difficile','Classez chaque bruit du quotidien selon la pièce de la maison où on l\'entend le plus souvent.','',4,'reconnaitre','{"categories": ["Cuisine", "Salle de bain", "Jardin", "Rue"], "consigne_categorisation": "Dans quelle pièce ou quel lieu entend-on le plus souvent ce bruit ?", "classification": [{"description": "Le sifflement d\'une bouilloire.", "categorie": "Cuisine"}, {"description": "L\'eau qui coule dans la douche.", "categorie": "Salle de bain"}, {"description": "Une tondeuse à gazon en marche.", "categorie": "Jardin"}, {"description": "Le klaxon d\'une voiture.", "categorie": "Rue"}, {"description": "Le mixeur qui broie des légumes.", "categorie": "Cuisine"}, {"description": "Le sèche-cheveux.", "categorie": "Salle de bain"}, {"description": "Le chant des oiseaux dans les arbres.", "categorie": "Jardin"}, {"description": "Une sirène de pompiers au loin.", "categorie": "Rue"}, {"description": "Le grille-pain qui éjecte les tartines.", "categorie": "Cuisine"}], "instructions": "Votre partenaire décrit un bruit. Dites dans quel lieu on l\'entend le plus souvent.", "consigne_partenaire": "Lisez chaque description à voix haute, dans un ordre aléatoire."}'),
(85,'Trouvez l\'intrus (mots)','facile','Une liste de mots est énoncée. Un seul n\'appartient pas au même thème que les autres : trouvez-le.','',4,'reconnaitre','{"listes_intrus": [{"items": ["chat", "chien", "cheval", "voiture"], "intrus": "voiture"}, {"items": ["pomme", "banane", "fraise", "chaise"], "intrus": "chaise"}, {"items": ["rouge", "bleu", "vert", "triste"], "intrus": "triste"}, {"items": ["table", "chaise", "armoire", "soleil"], "intrus": "soleil"}, {"items": ["lundi", "mardi", "jeudi", "avril"], "intrus": "avril"}], "instructions": "Votre partenaire énonce une liste de mots. Trouvez celui qui n\'appartient pas au même thème.", "consigne_partenaire": "Prononcez chaque liste de mots clairement, dans l\'ordre indiqué."}'),
(86,'Trouvez l\'intrus (syllabes proches)','moyen','Une liste de syllabes très proches est énoncée. Une seule diffère des autres par un trait phonétique : trouvez-la.','',4,'reconnaitre','{"listes_intrus": [{"items": ["pa", "pa", "ba", "pa"], "intrus": "ba"}, {"items": ["ta", "ta", "ta", "da"], "intrus": "da"}, {"items": ["fou", "fou", "vou", "fou"], "intrus": "vou"}, {"items": ["chi", "chi", "ji", "chi"], "intrus": "ji"}, {"items": ["ka", "ga", "ka", "ka"], "intrus": "ga"}], "instructions": "Votre partenaire prononce une série de syllabes très proches. Trouvez celle qui diffère des autres.", "consigne_partenaire": "Prononcez chaque série lentement et clairement, dans l\'ordre indiqué."}'),
(87,'Trouvez l\'intrus (phrases proches)','difficile','Une liste de phrases phonétiquement proches est énoncée. Une seule a un sens différent des autres : trouvez-la.','',4,'reconnaitre','{"listes_intrus": [{"items": ["Il fait beau", "Il fait chaud", "Il fait faux", "Il fait doux"], "intrus": "Il fait faux"}, {"items": ["Elle a ri", "Elle a lu", "Elle a su", "Elle a vu"], "intrus": "Elle a ri"}, {"items": ["Je pars demain", "Je cours demain", "Je dors demain", "Je sors demain"], "intrus": "Je cours demain"}], "instructions": "Votre partenaire prononce une série de phrases très proches. Trouvez celle dont le sens diffère des autres.", "consigne_partenaire": "Prononcez chaque série lentement et clairement, dans l\'ordre indiqué."}'),
(88,'Suivez la consigne (simple)','facile','Écoutez une consigne à une seule action et exécutez-la avec votre partenaire.','',6,'comprendre','{"phrases": ["Levez la main droite.", "Touchez votre nez.", "Fermez les yeux.", "Montrez la porte.", "Tapez dans vos mains."], "instructions": "Votre partenaire énonce une consigne simple. Exécutez-la, puis indiquez si vous avez réussi.", "consigne_partenaire": "Énoncez chaque consigne clairement, une seule action à la fois."}'),
(89,'Suivez la consigne (à deux étapes)','moyen','Écoutez une consigne à deux actions successives et exécutez-les dans l\'ordre.','',6,'comprendre','{"phrases": ["Levez la main puis touchez votre oreille.", "Fermez les yeux puis comptez jusqu\'à trois.", "Montrez la fenêtre puis asseyez-vous.", "Touchez votre tête puis tapez dans vos mains.", "Levez-vous puis tournez sur vous-même."], "instructions": "Votre partenaire énonce une consigne à deux étapes. Exécutez les deux actions dans l\'ordre, puis indiquez si vous avez réussi.", "consigne_partenaire": "Énoncez chaque consigne d\'une traite, sans répéter."}'),
(90,'Suivez la consigne (complexe)','difficile','Écoutez une consigne à plusieurs étapes, avec une condition, et exécutez-la.','',6,'comprendre','{"phrases": ["Si la porte est fermée, levez la main ; sinon, tapez dans vos mains.", "Touchez d\'abord votre nez, puis votre oreille gauche, puis asseyez-vous.", "Comptez jusqu\'à trois, puis fermez les yeux jusqu\'à ce qu\'on vous touche l\'épaule.", "Montrez la fenêtre si elle est ouverte, sinon montrez la porte."], "instructions": "Votre partenaire énonce une consigne complexe, avec plusieurs étapes ou une condition. Exécutez-la, puis indiquez si vous avez réussi.", "consigne_partenaire": "Énoncez la consigne complète d\'une traite, sans la répéter ni la simplifier."}'),
(91,'Dialogue du quotidien','moyen','Votre partenaire vous parle comme dans une conversation réelle. Répondez du mieux possible, avec lecture labiale si besoin.','',6,'comprendre','{"phrases": ["Qu\'est-ce que tu as prévu de faire ce week-end ?", "Est-ce que tu as bien dormi cette nuit ?", "Qu\'est-ce qu\'on mange ce soir, tu as une idée ?", "Tu as des nouvelles de la famille ?", "Comment s\'est passée ta journée ?"], "instructions": "Votre partenaire vous pose une question naturelle comme dans une vraie conversation. Répondez-y, puis indiquez si l\'échange s\'est bien passé.", "consigne_partenaire": "Posez chaque question naturellement, comme dans une conversation, en gardant votre visage visible."}'),
(92,'Conversation au téléphone','difficile','Votre partenaire vous parle depuis une autre pièce ou au téléphone : pas de lecture labiale possible, seul le son compte.','',6,'comprendre','{"phrases": ["Allô, tu m\'entends bien ?", "Je t\'appelle pour te dire que je serai en retard.", "Tu peux me rappeler ce soir vers dix-neuf heures ?", "Est-ce que tu as reçu le message que je t\'ai envoyé ?", "On se retrouve à quelle heure demain ?"], "instructions": "Votre partenaire vous parle sans que vous puissiez le voir (au téléphone ou depuis une autre pièce). Répondez comme dans un vrai appel, puis indiquez si vous avez bien compris.", "consigne_partenaire": "Lisez chaque phrase depuis une autre pièce, ou appelez réellement au téléphone, sans vous laisser voir."}');

