(93,'Quel mot avez-vous entendu ? (mots très différents)','facile','Écoutez le mot prononcé et retrouvez-le parmi des mots très différents.','',4,'decision_orthographique','{"mots": [{"mot": "chat", "choix": ["chat", "vélo", "arbre", "table"]}, {"mot": "maison", "choix": ["voiture", "maison", "soleil", "fleur"]}, {"mot": "livre", "choix": ["porte", "musique", "livre", "nuage"]}, {"mot": "jardin", "choix": ["jardin", "montagne", "cuisine", "bureau"]}, {"mot": "pomme", "choix": ["orange", "pomme", "banane", "raisin"]}, {"mot": "école", "choix": ["hôpital", "gare", "école", "magasin"]}], "instructions": "Votre partenaire prononce un mot. Retrouvez-le parmi les mots proposés.", "consigne_partenaire": "Prononcez clairement un seul mot parmi les quatre proposés, dans un ordre aléatoire."}'),
(94,'Quel mot avez-vous entendu ? (mots proches)','moyen','Écoutez le mot prononcé et retrouvez-le parmi des mots qui se ressemblent un peu.','',4,'decision_orthographique','{"mots": [{"mot": "poisson", "choix": ["poisson", "boisson", "poison", "prison"]}, {"mot": "bateau", "choix": ["bateau", "chapeau", "gâteau", "rideau"]}, {"mot": "manteau", "choix": ["manteau", "marteau", "morceau", "monceau"]}, {"mot": "caisse", "choix": ["caisse", "fraise", "chaise", "braise"]}, {"mot": "coussin", "choix": ["coussin", "cousin", "poussin", "moussu"]}, {"mot": "raisin", "choix": ["raisin", "requin", "rasoir", "raison"]}], "instructions": "Votre partenaire prononce un mot. Retrouvez-le parmi des mots qui se ressemblent.", "consigne_partenaire": "Prononcez clairement un seul mot parmi les quatre proposés, dans un ordre aléatoire."}'),
(95,'Quel mot avez-vous entendu ? (paires minimales)','difficile','Écoutez le mot prononcé et retrouvez-le parmi des mots qui ne diffèrent que d\'un seul son.','',4,'decision_orthographique','{"mots": [{"mot": "pain", "choix": ["pain", "bain", "vin", "lin"]}, {"mot": "tante", "choix": ["tante", "dante", "sente", "vente"]}, {"mot": "chou", "choix": ["chou", "joue", "coup", "roue"]}, {"mot": "pont", "choix": ["pont", "bond", "ton", "don"]}, {"mot": "gare", "choix": ["gare", "car", "mare", "bar"]}, {"mot": "vase", "choix": ["vase", "base", "case", "phase"]}], "instructions": "Votre partenaire prononce un mot. Retrouvez-le parmi des mots très proches phonétiquement.", "consigne_partenaire": "Prononcez clairement un seul mot parmi les quatre proposés, dans un ordre aléatoire."}');

