UPDATE `Exercices` SET `contenu` = '{"sons": [{"son": "La pluie", "description": "C\'est un bruit continu de gouttes qui tombent sur les vitres"}, {"son": "La sonnerie du téléphone", "description": "C\'est un son répétitif qui vous appelle à répondre"}, {"son": "Le micro-ondes", "description": "C\'est un bip court qui annonce que votre plat est chaud"}, {"son": "Un chien qui aboie", "description": "C\'est le cri d\'un animal domestique qui surveille la maison"}, {"son": "La cafetière", "description": "C\'est un gargouillis régulier qui prépare votre boisson du matin"}, {"son": "Une clé dans la serrure", "description": "C\'est un bruit métallique suivi d\'un clic quand on entre chez soi"}, {"son": "Un réveil qui sonne", "description": "C\'est un bip strident et répété qui vous sort du sommeil"}, {"son": "Une porte qui grince", "description": "C\'est un son aigu et prolongé quand on l\'ouvre lentement"}, {"son": "Le lave-linge en essorage", "description": "C\'est un vrombissement rapide et vibrant en fin de cycle"}, {"son": "Un verre qui se brise", "description": "C\'est un bruit sec et cristallin suivi de petits éclats"}, {"son": "Une scie électrique", "description": "C\'est un grondement aigu et continu qui découpe le bois"}, {"son": "Des pas dans l\'escalier", "description": "C\'est une série de bruits sourds et réguliers qui se rapprochent"}], "instructions": "Votre partenaire décrit un son sans le nommer. Devinez de quel son il s\'agit.", "consigne_partenaire": "Décrivez le son avec des mots, sans le nommer directement."}' WHERE `id` = 15;
