UPDATE `Exercices` SET `contenu` = '{"themes": [{"theme": "La journée", "questions": ["À quelle heure vous levez-vous en général ?", "Qu\'est-ce que vous mangez au petit-déjeuner ?", "Comment venez-vous ici ce matin ?", "Avez-vous bien dormi cette nuit ?", "Qu\'avez-vous fait hier soir ?"]}, {"theme": "Les loisirs", "questions": ["Qu\'aimez-vous faire le week-end ?", "Regardez-vous souvent la télévision ?", "Avez-vous un sport préféré ?", "Lisez-vous beaucoup ?", "Aimez-vous la musique ?"]}, {"theme": "La météo et les saisons", "questions": ["Quel temps fait-il aujourd\'hui ?", "Quelle saison préférez-vous ?", "Avez-vous déjà vu de la neige ?", "Est-ce qu\'il pleut souvent chez vous ?", "Aimez-vous les jours de grand soleil ?"]}, {"theme": "La famille et les amis", "questions": ["Voyez-vous souvent votre famille ?", "Avez-vous des frères et sœurs ?", "Qui est votre meilleur ami ?", "Vous parlez souvent au téléphone avec vos proches ?", "Avez-vous des petits-enfants ?"]}], "instructions": "Votre partenaire vous pose des questions. Répondez le plus naturellement possible.", "consigne_partenaire": "Posez chaque question clairement. Si l\'auditeur ne comprend pas, reformulez."}' WHERE `id` = 25;
UPDATE `Exercices` SET `contenu` = '{"sequences": [{"contexte": "Ingrédients d\'une recette", "elements": ["farine", "oeufs", "lait", "sucre", "beurre"]}, {"contexte": "Étapes du matin", "elements": ["réveil", "douche", "petit-déjeuner", "habillage", "départ"]}, {"contexte": "Directions", "elements": ["tout droit", "à gauche", "à droite", "tout droit", "à gauche"]}, {"contexte": "Jours de rendez-vous", "elements": ["lundi matin", "mercredi après-midi", "vendredi matin"]}, {"contexte": "Liste de courses", "elements": ["tomates", "fromage", "jambon", "yaourt", "jus d\'orange"]}, {"contexte": "Étapes pour préparer un café", "elements": ["eau", "filtre", "café moulu", "sucre"]}, {"contexte": "Villes de France", "elements": ["Paris", "Lyon", "Marseille", "Bordeaux", "Lille"]}, {"contexte": "Objets à emporter en vacances", "elements": ["maillot de bain", "lunettes de soleil", "crème solaire", "passeport"]}, {"contexte": "Étapes pour se laver les mains", "elements": ["mouiller", "savonner", "frotter", "rincer", "sécher"]}, {"contexte": "Numéros à retenir", "elements": ["deux", "sept", "quatre", "neuf", "un"]}], "instructions": "Votre partenaire lit une liste de 4 à 5 éléments. Répétez-les dans le même ordre.", "consigne_partenaire": "Lisez la liste une seule fois à vitesse normale. Attendez 10 secondes avant de demander la réponse."}' WHERE `id` = 27;
UPDATE `Exercices` SET `contenu` = '{"histoires": [{"texte": "Marie se lève tôt le samedi matin. Elle prend son panier en osier et marche jusqu\'au marché du quartier. Elle achète des légumes frais : des carottes, des poireaux et des champignons. Elle s\'arrête aussi chez le fromager pour prendre un camembert. En rentrant, elle croise son voisin Paul qui promène son chien.", "titre": "Le marché du samedi", "questions": [{"reponse": "Le samedi", "question": "Quel jour Marie va-t-elle au marché ?"}, {"reponse": "Un panier en osier", "question": "Qu\'est-ce qu\'elle emporte pour faire ses courses ?"}, {"reponse": "Carottes, poireaux ou champignons", "question": "Citez deux légumes qu\'elle achète."}, {"reponse": "Un camembert", "question": "Qu\'achète-t-elle chez le fromager ?"}, {"reponse": "Son voisin Paul", "question": "Qui croise-t-elle en rentrant ?"}]}, {"texte": "Thomas a rendez-vous chez le médecin à quatorze heures trente. Il attend vingt minutes dans la salle d\'attente. Le médecin l\'examine et lui dit qu\'il a une légère grippe. Il lui prescrit du repos, beaucoup de liquides et lui donne une ordonnance. Thomas doit revenir dans une semaine si les symptômes persistent.", "titre": "Le rendez-vous médical", "questions": [{"reponse": "Quatorze heures trente", "question": "À quelle heure est le rendez-vous de Thomas ?"}, {"reponse": "Vingt minutes", "question": "Combien de temps attend-il ?"}, {"reponse": "Une légère grippe", "question": "Quel est le diagnostic ?"}, {"reponse": "Du repos et beaucoup de liquides", "question": "Que lui conseille le médecin ?"}, {"reponse": "Dans une semaine", "question": "Quand doit-il revenir ?"}]}, {"titre": "La randonnée en montagne", "texte": "Le dimanche matin, Julien part en randonnée avec deux amis. Ils montent pendant deux heures jusqu\'à un petit lac de montagne. Ils pique-niquent sur un rocher en admirant le paysage. Sur le chemin du retour, il commence à pleuvoir et ils doivent accélérer le pas. Ils rentrent trempés mais heureux de leur journée.", "questions": [{"question": "Quel jour Julien part-il en randonnée ?", "reponse": "Le dimanche"}, {"question": "Avec combien d\'amis part-il ?", "reponse": "Deux amis"}, {"question": "Où pique-niquent-ils ?", "reponse": "Sur un rocher, près d\'un lac de montagne"}, {"question": "Que se passe-t-il sur le chemin du retour ?", "reponse": "Il commence à pleuvoir"}, {"question": "Comment rentrent-ils ?", "reponse": "Trempés mais heureux"}]}], "instructions": "Votre partenaire lit une courte histoire. Écoutez attentivement, puis répondez aux questions.", "consigne_partenaire": "Lisez l\'histoire une fois à voix haute. Posez ensuite les questions une par une."}' WHERE `id` = 28;
UPDATE `Exercices` SET `contenu` = '{"listes": [{"theme": "Choses à faire aujourd\'hui", "elements": ["appeler le médecin", "acheter du pain", "arroser les plantes", "rappeler Sophie", "prendre les médicaments", "sortir les poubelles"]}, {"theme": "Pays d\'Europe", "elements": ["France", "Allemagne", "Italie", "Espagne", "Portugal", "Belgique", "Suisse"]}, {"theme": "Animaux de la ferme", "elements": ["vache", "cochon", "mouton", "chèvre", "canard", "poule", "lapin", "cheval"]}, {"theme": "Objets de la salle de bain", "elements": ["savon", "serviette", "brosse à dents", "shampoing", "rasoir"]}, {"theme": "Métiers", "elements": ["médecin", "boulanger", "professeur", "pompier", "facteur", "infirmière"]}, {"theme": "Couleurs", "elements": ["rouge", "bleu", "jaune", "vert", "orange", "violet", "noir"]}], "instructions": "Votre partenaire vous lit une liste. Vous discutez d\'autre chose pendant 2 minutes, puis vous rappelez le maximum d\'éléments.", "consigne_partenaire": "Lisez la liste lentement. Pendant 2 minutes, parlez d\'autre chose. Demandez ensuite quels éléments ont été retenus."}' WHERE `id` = 29;

